// === Inspired by 'Recursiverectanglepacking' by 'Roni Kaufman' ===
// Created as variant #5 by Uncler M
// Infused with creative algorithmic modifications.

// === Tab: sketch ===
// By Roni Kaufman
// https://ronikaufman.github.io

let M, N, u, gap, corner;
let myWhite = "#fafafa", myBlack = "#0a0a0a", accentCol;

let randInt = (a, b) => (floor(random(a, b))); 

function setup() {
  createCanvas(500, 500);
  pixelDensity(4);
	noStroke();
	noLoop();

	M = 10;
	N = M;
	let margin = 50;
	u = (width-2*margin) / M;
	gap = u/8;
	corner = (u/4-gap)/2;

	accentCol = random(["#f589a3", "#ef562f", "#f9d531", "#abcd5e", "#69bcea"]);

	let iMin = 0, iMax = M, jMin = 0, jMax = N;
	let siMax = ~~(M/2);
	let sjMax = ~~(N/2);
	let rectangles = createComposition(iMin, iMax, jMin, jMax, siMax, sjMax, 1000);

	background(myWhite);

	translate(margin, margin);
  for (let recta of rectangles) {
		drawRectangle(recta, u, myBlack);
		recta.depth = 0;

		let iMin1 = 4*recta.i;
		let iMax1 = 4*(recta.i+recta.si) - 1;
		let jMin1 = 4*recta.j;
		let jMax1 = 4*(recta.j+recta.sj) - 1;
		let siMax1 = round(4*recta.si/2);
		let sjMax1 = round(4*recta.sj/2);
		let possibleCols = [accentCol, myWhite];
		createSubcompo(iMin1, iMax1, jMin1, jMax1, siMax1, sjMax1, possibleCols, 500);
	}
}

// creating the composition

function createComposition(iMin, iMax, jMin, jMax, siMax, sjMax, nRects) {
	let rectangles = [];

	for (let i = 0; i < nRects; i++) {
    let newRecta = generateRectangle(rectangles, iMin, iMax, jMin, jMax, siMax, sjMax);
    if (((newRecta.si > 1 || newRecta.sj > 1) && random() < 1/2) || (newRecta.si > 1 && newRecta.sj > 1)) { // no 1x1 squares and avoid thin rectangles
      rectangles.push(newRecta);
    }
  }

  // fill the gaps with 1x1 rectangles
	for (let i = iMin; i < iMax; i++) {
		for (let j = jMin; j < jMax; j++) {
			let newRecta = {
				i: i,
				j: j,
				si: 1,
				sj: 1
			}
			let canAdd = true;
			for (let recta of rectangles) {
				if (rectanglesIntersect(newRecta, recta)) {
					canAdd = false;
					break;
				}
			}
			if (canAdd) {
				rectangles.push(newRecta);
			}
		}
	}

	return rectangles;
}

function rectanglesIntersect(recta1, recta2) {
	return ((recta1.i <= recta2.i && recta1.i+recta1.si > recta2.i) || (recta2.i <= recta1.i && recta2.i+recta2.si > recta1.i)) && ((recta1.j <= recta2.j && recta1.j+recta1.sj > recta2.j) || (recta2.j <= recta1.j && recta2.j+recta2.sj > recta1.j));
}

function generateRectangle(rectangles, iMin, iMax, jMin, jMax, siMax, sjMax) {
  let i = randInt(iMin, iMax);
  let j = randInt(jMin, jMax);

	// determine biggest possible size
	let si, sj;
	if (rectangles.length == 0) {
		si = min(siMax, iMax-i);
		sj = min(sjMax, jMax-j);
	} else {
		let si1 = biggestPossibleWidth(rectangles, iMax, siMax, i, j, 1, 1);
		let sj1 = biggestPossibleHeight(rectangles, jMax, sjMax, i, j, si1, 1);

		let sj2 = biggestPossibleHeight(rectangles, jMax, sjMax, i, j, 1, 1);
		let si2 = biggestPossibleWidth(rectangles, iMax, siMax, i, j, 1, sj2);

		if (si1*sj1 > si2*sj2) {
			si = si1;
			sj = sj1;
		} else {
			si = si2;
			sj = sj2;
		}
	}

	if (random() < 1/2) { // avoid squares
		if (si == sj && si > 1) {
			if (random() < 1/2) {
				si--;
			} else {
				sj--;
			}
		}
	}

  let recta = {
    i: i,
    j: j,
    si: si,
		sj: sj
  };
  return recta;
}

function biggestPossibleWidth(rectangles, iMax, siMax, i, j, si, sj) {
	let s = si;
	let intersects = false;
	while (!intersects) {
		s++;
		for (let recta of rectangles) {
			if (i+s > iMax || s > siMax || rectanglesIntersect({i: i, j: j, si: s, sj: sj}, recta)) {
				intersects = true;
				break;
			}
		}
	}
	return s-1;
}

function biggestPossibleHeight(rectangles, jMax, sjMax, i, j, si, sj) {
	let s = sj;
	intersects = false;
	while (!intersects) {
		s++;
		for (let recta of rectangles) {
			if (j+s > jMax || s > sjMax || rectanglesIntersect({i: i, j: j, si: si, sj: s}, recta)) {
				intersects = true;
				break;
			}
		}
	}
	return s-1;
}

// recursive part

function createSubcompo(iMin1, iMax1, jMin1, jMax1, siMax1, sjMax1, possibleCols, nRects) {
	let subrectangles = createComposition(iMin1, iMax1, jMin1, jMax1, siMax1, sjMax1, nRects);
	for (let subrecta of subrectangles) {
		push();
		translate(u/8, u/8);
		let col = random(possibleCols);
		drawRectangle(subrecta, u/4, col);
		if (subrecta.si > 1 && subrecta.sj > 1) {
			let iMin2 = subrecta.i;
			let iMax2 = iMin2 + subrecta.si - 1;
			let jMin2 = subrecta.j;
			let jMax2 = jMin2 + subrecta.sj - 1;
			let siMax2 = round(subrecta.si/2);
			let sjMax2 = round(subrecta.sj/2);
			let possibleSubCols = col == myBlack ? [accentCol, myWhite] : (col == myWhite ? [myBlack, accentCol] : [myWhite, myBlack]);
			createSubcompo(iMin2, iMax2, jMin2, jMax2, siMax2, sjMax2, possibleSubCols, nRects);
		}
		pop();
	}
}

// drawing

function drawRectangle(recta, s, col) {
	let x = recta.i*s + gap/2, y = recta.j*s + gap/2;
	let w = recta.si*s - gap, h = recta.sj*s - gap;
	fill(col);
	rect(x, y, w, h, corner);
}

